// v16.xx (hudsafe1), the cloud review (2026-10-15, finding 28): HUD DRAWS AND FLOW TICKS ARE NOT EXCEPTION-SAFE. Each draw of the raid flow
// and the party (the fires, the air strike, the events, the strongholds, the golden enemy, the power-ups, the combo rings) saves the canvas
// state, may switch to additive blending, and restores at its end, so one bad number (a non finite radius in a gradient) left the saved
// state unbalanced and the blend mode on for every HUD piece drawn after it, in every later frame, with the save stack growing. hudGuard
// runs a draw with its saves and restores counted: whatever it left open is closed, and the blend mode, the alpha and the dash are put
// back, whether it threw or not (a throw is swallowed here, as the callers did). The flow ticks each have a try of their own, so one
// throw stops that one tick for that frame and never the ones after it.
function hudGuard(c,fn){
  var depth=0, sv=c.save, rs=c.restore, ok=true;
  c.save=function(){ depth++; return sv.apply(c,arguments); };
  c.restore=function(){ depth--; return rs.apply(c,arguments); };
  try{ fn(); }catch(_hg){ ok=false; }
  finally {
    delete c.save; delete c.restore;
    while(depth>0){ try{ rs.call(c); }catch(_r){} depth--; }
    try{ c.globalCompositeOperation='source-over'; c.globalAlpha=1; c.setLineDash([]); c.shadowBlur=0; }catch(_s){}
  }
  return ok;
}
